<script setup lang="ts">
import { computed,ref,watch } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { ElMessage,ElMessageBox } from 'element-plus'
import { api,errorText } from '../api/http'
import { businessConfig,primaryAction,kindLabel,type Resource } from '../api/business'
import { useAuthStore } from '../stores/auth'
import { dateTime,money } from '../utils/format'
import type { Row } from '../types'
import StatusTag from '../components/StatusTag.vue'
import BusinessForm from '../components/BusinessForm.vue'
const route=useRoute(),router=useRouter(),auth=useAuthStore(),resource=computed(()=>route.meta.resource as Resource),config=computed(()=>businessConfig[resource.value])
const row=ref<Row>(),loading=ref(false),busy=ref(false),error=ref(''),drawer=ref(false),requirements=ref<Row>(),requirementsError=ref('')
const action=computed(()=>row.value?primaryAction(resource.value,row.value.status):null)
const steps=['DRAFT','READY_TO_ISSUE','IN_PRODUCTION','PENDING_INBOUND','COMPLETED']
const currentBom=ref<Row>(),bomError=ref('')
watch(()=>row.value?.bomId,async id=>{currentBom.value=undefined;bomError.value='';if(resource.value!=='production'||row.value?.status!=='DRAFT'||!id||!auth.can('mes:bom:read'))return;try{currentBom.value=(await api.get(`/boms/${id}`)).data}catch(e){bomError.value=errorText(e)}})
async function load(){loading.value=true;error.value='';requirements.value=undefined;try{row.value=(await api.get(`${config.value.path}/${route.params.id}`)).data}catch(e){error.value=errorText(e)}finally{loading.value=false}}
async function preview(){requirementsError.value='';try{requirements.value=(await api.get(`${config.value.path}/${route.params.id}/material-requirements`)).data}catch(e){requirementsError.value=errorText(e)}}
function confirmation(key:string){const r=row.value!; const lines=(key==='issue'?r.materialSnapshot:r.items)||[]; const warehouse=key==='issue'?r.issueWarehouseName:r.warehouseName; if(key==='report')return `按计划量一次性报工：${r.productName} ${r.plannedQuantity} ${r.unit}。报工不增加整机库存，随后须执行整机入库。`; if(key==='confirm')return `确认 ${r.orderNo} 后，单据不可编辑、取消或反冲。${resource.value==='production'?'将冻结当前BOM和物料快照。':''}`;if(key==='cancel')return `取消草稿 ${r.orderNo}，取消后不能继续处理。`;if(key==='delete')return `永久删除草稿 ${r.orderNo}？`;return `仓库：${warehouse}。全部数量：${lines.map((i:Row)=>`${i.materialName} ${i.requiredQuantity||i.quantity} ${i.unit||''}`).join('；')}。整单一次执行，完成后不能撤回或反冲。`}
async function run(key:string){if(busy.value||!row.value)return;busy.value=true;try{await ElMessageBox.confirm(confirmation(key),key==='delete'?'删除草稿':'确认业务操作',{confirmButtonText:'确认提交',cancelButtonText:'返回',type:'warning'})}catch{busy.value=false;return}error.value='';try{if(key==='delete'){await api.delete(`${config.value.path}/${row.value.id}`,{params:{version:row.value.version}});ElMessage.success('草稿已删除');await router.push(config.value.route)}else{await api.post(`${config.value.path}/${row.value.id}/${key}`,{version:row.value.version});ElMessage.success(key==='report'?'报工成功，整机库存尚未增加':'操作成功');await load()}}catch(e){error.value=errorText(e);if((e as {response?:{status?:number}}).response?.status===409){const text=error.value;await load();error.value=text}}finally{busy.value=false}}
watch(()=>route.fullPath,()=>{row.value=undefined;void load()},{immediate:true})
</script>
<template>
 <div class="page-header"><div><h1>{{row?.orderNo || config.title}}</h1></div><div><el-button @click="router.push(config.route)">返回列表</el-button><template v-if="row"><el-button v-if="action && auth.can(config.permission+':'+action.key)" type="primary" :loading="busy" @click="run(action.key)">{{action.label}}</el-button><template v-if="row.status==='DRAFT' && auth.can(config.permission+':write')"><el-button :disabled="busy" @click="drawer=true">编辑草稿</el-button><el-button :loading="busy" @click="run('cancel')">取消草稿</el-button><el-button type="danger" plain :loading="busy" @click="run('delete')">删除草稿</el-button></template></template></div></div>
 <div v-if="error" class="error-box" role="alert">{{error}} <el-button link @click="load">重试</el-button></div><el-skeleton v-if="loading&&!row" :rows="8" animated />
 <template v-if="row">
 <section v-if="resource==='production'&&row.status==='DRAFT'" class="panel"><h2>当前 BOM 预览</h2><p class="muted">当前内容仅供预览，确认时后端重新读取启用 BOM 并冻结用料快照。</p><div v-if="bomError" class="error-box">{{bomError}}</div><el-table v-if="currentBom" :data="currentBom.items"><el-table-column prop="materialCode" label="原料编码"/><el-table-column prop="materialName" label="原料名称"/><el-table-column prop="quantityPer" label="单台用量"/><el-table-column prop="unit" label="单位"/></el-table></section>
 <section class="panel"><el-descriptions :column="3" border><el-descriptions-item label="状态"><StatusTag :value="row.status" /></el-descriptions-item><el-descriptions-item label="创建时间">{{dateTime(row.createdAt)}}</el-descriptions-item><el-descriptions-item label="创建人">{{row.createdByName}}</el-descriptions-item><template v-if="resource==='production'"><el-descriptions-item label="成品">{{row.productCode}} · {{row.productName}}</el-descriptions-item><el-descriptions-item label="计划数量">{{row.plannedQuantity}} {{row.unit}}</el-descriptions-item><el-descriptions-item label="BOM">{{row.bomCode}} / 修订 {{row.bomRevision ?? '待确认'}}</el-descriptions-item><el-descriptions-item label="领料仓库">{{row.issueWarehouseName}}</el-descriptions-item><el-descriptions-item label="入库仓库">{{row.receiptWarehouseName}}</el-descriptions-item></template><template v-else><el-descriptions-item :label="resource==='purchase'?'供应商':'客户'">{{row.supplierName||row.customerName}}</el-descriptions-item><el-descriptions-item label="仓库">{{row.warehouseName}}</el-descriptions-item><el-descriptions-item label="总金额">{{money(row.totalAmount)}}</el-descriptions-item></template><el-descriptions-item label="备注" :span="3">{{row.remark||'—'}}</el-descriptions-item></el-descriptions></section>
 <section v-if="resource!=='production'" class="panel"><h2>单据进度</h2><el-alert v-if="row.status==='CANCELLED'" title="单据已取消" type="info" :closable="false"/><el-steps v-else :active="row.status==='DRAFT'?0:row.status==='CONFIRMED'?1:3" finish-status="success" align-center><el-step title="草稿"/><el-step title="已确认"/><el-step :title="resource==='purchase'?'已收货':'已发货'"/></el-steps></section><section v-if="resource==='production'" class="panel"><h2>生产进度</h2><el-alert v-if="row.status==='CANCELLED'" title="工单已取消" type="info" :closable="false"/><el-steps v-else :active="row.status==='COMPLETED'?steps.length:steps.indexOf(row.status)" finish-status="success" align-center><el-step title="草稿"/><el-step title="待领料"/><el-step title="生产中"/><el-step title="待入库"/><el-step title="已完成"/></el-steps><p v-if="row.confirmedAt" class="muted">确认时BOM及物料快照已冻结，后续BOM修订不影响本工单。</p><el-alert v-if="row.report" :title="`已报工${row.report.reportedQuantity}${row.unit} · ${dateTime(row.report.reportedAt)} · ${row.report.reportedByName}${row.status==='PENDING_INBOUND'?'；整机库存尚未增加，请执行关联入库单':''}`" :closable="false" type="info"/></section>
 <section class="panel"><h2>{{resource==='production'?'确认物料快照':'单据明细'}}</h2><el-table :data="resource==='production'?row.materialSnapshot:row.items" empty-text="确认工单后生成物料快照"><el-table-column prop="materialCode" label="物料编码" min-width="150"/><el-table-column prop="materialName" label="物料名称" min-width="170"/><el-table-column prop="unit" label="单位" width="80"/><el-table-column v-if="resource==='production'" prop="quantityPer" label="单台用量" width="120" align="right"/><el-table-column :prop="resource==='production'?'requiredQuantity':'quantity'" label="全部数量" width="120" align="right"/><template v-if="resource!=='production'"><el-table-column prop="unitPrice" label="含税单价（元）" width="130" align="right"/><el-table-column prop="lineAmount" label="金额（元）" width="150" align="right"/></template></el-table></section>
 <section v-if="resource==='production' && row.status!=='CANCELLED' && auth.can('wms:stock:read')" class="panel"><h2>缺料预览</h2><p class="muted">当前库存仅供参考，正式领料将重新检查。</p><el-button @click="preview">查询当前物料需求</el-button><div v-if="requirementsError" class="error-box">{{requirementsError}}</div><el-table v-if="requirements" :data="requirements.items"><el-table-column prop="materialName" label="物料"/><el-table-column prop="requiredQuantity" label="需求数量" align="right"/><el-table-column prop="availableQuantity" label="当前库存" align="right"/><el-table-column prop="shortageQuantity" label="缺料数量" align="right"/></el-table></section>
 <section class="panel"><h2>关联库存单</h2><el-table :data="row.stockDocuments" empty-text="暂无关联库存单"><el-table-column label="单号" min-width="210"><template #default="{row:doc}"><router-link v-if="auth.can('wms:document:read')" :to="`/wms/${doc.direction==='IN'?'inbound':'outbound'}/${doc.id}`">{{doc.documentNo}}</router-link><span v-else>{{doc.documentNo}}</span></template></el-table-column><el-table-column label="业务类型"><template #default="{row:doc}">{{kindLabel(doc.kind)}}</template></el-table-column><el-table-column prop="warehouseName" label="仓库"/><el-table-column label="状态"><template #default="{row:doc}"><StatusTag :value="doc.status"/></template></el-table-column></el-table></section>
 </template><el-drawer v-model="drawer" title="编辑草稿" size="min(620px, 100%)" destroy-on-close><BusinessForm :resource="resource" :initial="row" @cancel="drawer=false" @saved="drawer=false;load()"/></el-drawer>
</template>
